let inputData = $('When Executed by Another Workflow').first().json.transaction;
let candidates = $input.first().json;

let systemMessage = `You are a financial transaction classification engine.

Your task is to classify bank transactions into:

- merchant_name
- category_name
- budget_name
- tags

Rules:

1. Return ONLY valid JSON.
2. Never return markdown.
3. Never return explanations.
4. merchant_name must be normalized:
   - "SPAR DOO MARIBOR" -> "Spar"
   - "LIDL SLOVENIJA D.O.O." -> "Lidl"
   - "MERKUR ZAVAROVALNICA" -> "Merkur Zavarovalnica"
5. category_name should be broad and stable.
6. budget_name should represent a long-term budgeting group.
7. tags should be short lowercase labels.
8. confidence must be between 0 and 1.
9. source must always be "ai".
10. If uncertain, make the best guess and lower confidence.

Output schema:

{
  "merchant_name": "string",
  "category_name": "string",
  "budget_name": "string|null",
  "tags": ["string"],
  "source": "ai",
  "confidence": 0.00
}`;

let description = inputData.description || '';
let amount = inputData.amount || 0.0;
let currency = inputData.currency_code || 'EUR';
let type = inputData.type || '';
let sdl = type == 'deposit' ? 'source_' : 'destination_';
let name = type == 'deposit' ? inputData.source_name : inputData.destination_name;
let notes = inputData.notes || '';

// ----------- creating candidates ----------------------------
let existingMerchants = (candidates.merchants || []).join(', ');
let existingBudgets = (candidates.budgets || []).join(', ');
let existingCategories = (candidates.categories || []).join(', ');
let existingTags = (candidates.tags || []).join(', ');

let alreadyExistingAddition = '';
if(existingMerchants || existingBudgets || existingCategories || existingTags){
  alreadyExistingAddition = `Choose existing values whenever possible.

The existing values:

${existingMerchants ? 'existing merchants: ' + existingMerchants : ''}

${existingBudgets ? 'existing budgets: ' + existingBudgets : ''}

${existingCategories ? 'existing categories: ' + existingCategories : ''}

${existingTags ? 'existing tags: ' + existingTags : ''}

Only create a new category, budget or tag if no existing value fits.
    `; 
}
// ------------------------------------------------------------


let prompt = `Classify this financial transaction.

Transaction:

{
  "description": "${description}",
  "amount": "${amount}",
  "currency": "${currency}",
  "type": "${type}",
  "${sdl}name": "${name}",
  "notes": "${notes}"
}

${alreadyExistingAddition}

Return JSON only.`;

let schema = {
  "type": "object",
  "properties": {
    "merchant_name": {
      "type": ["string","null"]
    },
    "category_name": {
      "type": ["string","null"]
    },
    "budget_name": {
      "type": ["string","null"]
    },
    "tags": {
      "type": "array",
      "items": {
        "type": ["string","null"]
      }
    },
    "source": {
      "type": ["string","null"]
    },
    "confidence": {
      "type": "number"
    }
  },
  "additionalProperties":false,
  "required": [
    "merchant_name",
    "category_name",
    "budget_name",
    "tags",
    "source",
    "confidence"
  ]
};

return [{json:{
  systemMessage,
  prompt,
  tokens: 5000,
  temperature: 0.1,
  model:'gpt-5-mini',
  engine:'openai',
  schema
}}];

let inputData = $('When Executed by Another Workflow').first().json.transaction;

let description = (inputData.description + (inputData.source_name || inputData.destination_name || '')).trim();

let resultData = {
  "description": description,
  "neighbors": 100,
  "limit": 20
};

return [{json:{parameters: JSON.stringify(resultData)}}];

let inputData = $('When Executed by Another Workflow').first().json.transaction;
let aiClassification = $input.first().json.output;

let rawTransaction = JSON.stringify(inputData);

let budget = aiClassification.budget_name != null ? {'budget_name': aiClassification.budget_name} : {};
let category = aiClassification.catgory_name != null ? {'category_name': aiClassification.category_name} : {};
let merchant = aiClassification.merchant_name != null ? {'merchant_name': aiClassification.merchant_name} : {};

let result = {
  "description": inputData.description,
  "normalized_description": inputData.description.toLowerCase().trim(),
  "raw_transaction": rawTransaction,
  ...merchant,
  ...category,
  ...budget,
  "tags": aiClassification.tags,
  "source": aiClassification.source,
  "confidence": aiClassification.confidence
};
return [{json:result}]

let aiOutput = $('Classificate Data').first().json.output;

let result = {
  merchant: aiOutput.merchant_name,
  category: aiOutput.category_name,
  budget: aiOutput.budget_name,
  tags: aiOutput.tags
};

return [{json: result}];

let inputData = $input.first().json.transaction;

let description = [inputData.description, (inputData.source_name || inputData.destination_name || '')].filter(n => n).join(' ').trim();

let resultData = {
  "description": description,
  "amount":inputData.amount || 0.0,
  "currency":inputData.currency_code || "EUR",
  "iban": inputData.source_iban || inputData.destination_iban || null
};

return [{json:{parameters: JSON.stringify(resultData)}}];

